// biome-ignore-all lint/suspicious/noTemplateCurlyInString: `${CLAUDE_PLUGIN_ROOT}` and `${__dirname}` are literal bytes of a Claude Code hook definition and an .mcpb manifest. The hosts expand them; this file must not.

/**
 * Every host-side template, compiled into the binary.
 *
 * THIS FILE IS A COPY. The canonical, reviewable assets live in `surfaces/` at
 * the repository root, and `test/surfaces.test.ts` fails the build if this file
 * and that directory disagree by a single byte, in either direction, for any
 * file. Edit `surfaces/`, then bring this file to match; never the reverse, and
 * never only one of them.
 *
 * THE COPY IS NOT AVOIDABLE, and it is worth saying why rather than leaving a
 * reader to assume it is sloppiness. brigadier ships as ONE FILE: a native
 * executable produced by `bun build --compile`. A user who installed it with a
 * single `curl` has no `surfaces/` directory on their machine, and
 * `brigadier install` still has to be able to write the doctrine. So the bytes
 * have to be inside the binary. Keeping them ALSO as real files is what makes
 * them reviewable in a diff, greppable, and testable against the thing that
 * ships — and the equality test is what keeps the two from becoming two
 * different products.
 *
 * `surfaces/README.md` is deliberately absent from this map: it documents the
 * directory for a reader of the repository and is never installed anywhere.
 *
 * Keys are paths relative to `surfaces/`. `src/surfaces/install.ts` maps each
 * one to its destination on the user's machine.
 */

export const SURFACE_TEMPLATES: Readonly<Record<string, string>> =
  Object.freeze({
    "claude-code/.claude-plugin/plugin.json":
      '{\n  "name": "brigadier",\n  "description": "You are not the worker: hand coding work to the brigadier CLI.",\n  "author": {\n    "name": "brigadier"\n  }\n}\n',
    "claude-code/SKILL.md":
      '---\nname: brigadier\ndescription: Load before starting any coding task with more than one independent piece of work — a feature, a cross-file refactor, a migration, a bug with several call sites, a batch of mechanical edits. Routes the work to the brigadier CLI instead of doing it in this session.\n---\n\n# You are not the worker\n\nThis machine has `brigadier` installed, and you are the one who runs it. When a\ntask decomposes into independent pieces, you do not write them here. You plan\nthem, invoke `brigadier run` yourself from inside this session, and review what\ncomes back. Your context is for coordination and judgement; a worker session is\ndisposable and starts clean.\n\n## If you are already a brigadier worker, stop here\n\n**A brigadier worker must never invoke brigadier.** If the prompt you were given\nis one slice of somebody else\'s plan — it names an `id`, the paths you own, and\nthe evidence you owe — then you are the worker, and the work in front of you is\nthe work you do. Spawning a second orchestrator from inside a slice spends the\nwhole slice and lands nothing. This has happened. brigadier stamps\n`BRIGADIER_WORKER=1` into every worker\'s environment, which is enough to keep the\nnudge hook quiet inside a worker but does not stop you: nothing in the product\nrefuses a second run, so this paragraph is what prevents it.\n\n## What to do\n\n1. **Decompose.** Disjoint `ownedPaths` are necessary, but they do not by\n   themselves make slices independent. If one slice needs another\'s committed\n   output, declare that real dependency in `dependsOn`. Dependencies place work\n   in later serial waves; independent slices share a wave and can run\n   concurrently, up to `--max-workers`. Partition by file ownership, not by\n   topic.\n2. **Write a plan document** (JSON):\n\n   ```json\n   {\n     "id": "add-retry",\n     "goal": "Retry transient HTTP failures in the client",\n     "slices": [\n       {\n         "id": "retry-core",\n         "title": "Retry loop and backoff",\n         "prompt": "One self-contained brief: the interfaces, the constraints, the definition of done, and the evidence required.",\n         "ownedPaths": ["src/http/retry.ts"],\n         "difficulty": "standard"\n       }\n     ]\n   }\n   ```\n\n   `id`, `title`, `prompt`, `ownedPaths` and `difficulty` are required on every\n   slice. `difficulty` is one of `routine`, `standard`, `hard`, and it has no\n   default: a plan that does not say how hard a slice is has not been planned.\n   `dependsOn` is optional and names prerequisite slice ids. brigadier runs\n   dependency waves in order and reconciles each non-final wave before creating\n   the next wave\'s worktrees, so dependent slices start from their prerequisites\'\n   committed output. Unknown ids, self-dependencies, and cycles are refused.\n   `requires` is optional and takes `imageInput`, `webSearch`,\n   `structuredOutput`, `commandExecution`, and `minContextWindowTokens`.\n3. **Dry-run it first.** `brigadier run --plan plan.json --dry-run` routes every\n   slice and reports it, without creating a worktree or spawning anything. Add\n   `--verbose` to see which vendor, model and effort would take each slice. A\n   slice that cannot route is worth knowing about before a worker is spent on\n   its siblings.\n4. **Run it.** `brigadier run --plan plan.json --max-workers 3`. Each slice gets\n   its own git worktree and its own branch; what lands is merged onto one\n   integration branch.\n5. **Review the diffs.** You own the outcome. A worker\'s report is a claim, not\n   evidence.\n\n## What not to do\n\n- Do not edit a file while a slice that owns it is running.\n- Do not do the work yourself because it "looks quick". A one-file change is a\n  one-slice plan, and writing the plan costs less than the context you spend\n  doing it here.\n- Do not hand the user a command to type. You have a shell; run `brigadier`\n  yourself and report what it did.\n- Do not invent commands. brigadier has exactly four: `run`, `install`, `mcp`,\n  and `init`. `brigadier run "<task description>"` asks a model to decompose the\n  task, then sends the result through the same validator used for `--plan`. On\n  genuine ambiguity it exits 4 with `status: "needs_human"` and structured\n  questions; no worktree is created and no slice worker is spawned.\n\n## There is no setup step\n\nConfiguration is automatic. `brigadier run` probes this machine for installed\nworker CLIs, writes `$BRIGADIER_HOME/config.json` — `~/.brigadier/config.json` by\ndefault — when none is there, and carries on. Never run `brigadier init` to make\na config appear: it has never been a prerequisite for a run, and a turn spent on\nit is a turn wasted. The one exception is not yours to take. Registering\nbrigadier\'s MCP server into a GUI application\'s own configuration takes a human\'s\nexplicit yes, and only the interactive question can ask for it — so if\n`brigadier install` reports a registration skipped for want of consent, pass that\nsentence to the user and let them run `brigadier init` once themselves.\n\n## Exit codes worth branching on\n\n`0` succeeded · `1` setup or planning failed, or the runner threw before returning\na report · `2` usage error · `3` a run report says the run failed, including\nschedulability or routing failures that created no worktree · `4` the planner needs\nhuman input (questions were printed; no slice worker, ref, or worktree was created)\n· `130`/`143` interrupted.\n',
    "claude-code/hooks/README.md":
      '# The hooks on Claude Code\n\n**Status: both work, with no click and no trust prompt.**\n\n`hooks.json` registers two commands, and `${CLAUDE_PLUGIN_ROOT}` is expanded by\nClaude Code to the installed skill directory, so both registrations survive being\ninstalled anywhere.\n\n| Script | Event | Fires when |\n| --- | --- | --- |\n| `handoff.mjs` | `PreCompact` | the session is about to compact |\n| `nudge.mjs` | `UserPromptSubmit` | a prompt describes more than one piece of work |\n\n## The handoff hook\n\n`PreCompact` fires when the session is about to compact — which is to say, when\nit has run out of context. That is the exact moment the doctrine is most needed\nand least likely to be followed, so it is where the hook lives. The event carries\n`transcript_path`, which is what makes the hook *transcript-watching* rather than\nmerely periodic: it reports how many assistant turns were spent before the\nhandoff.\n\n## The nudge hook\n\nThe skill\'s own description only fires when the model happens to notice it, which\nis the wrong thing to depend on at the moment a multi-part task arrives.\n`UserPromptSubmit` fires on the prompt itself. `UserPromptSubmit` takes no\nmatcher on this host, so the registration carries none.\n\n**Restraint is the design constraint, not coverage.** A hook that speaks every\nturn gets uninstalled within a day, and an uninstalled hook nudges nobody. So\n`nudge.mjs` is silent for an ordinary prompt, silent for anything under 120\ncharacters, and silent for the rest of the session once it has spoken.\n\nTwo refusals come before anything is counted. **A question is never enough**,\nhowever many bullets of symptoms follow it — an opening question with three\nbulleted symptoms is one bug report, not three pieces of work. **A fenced block\nis quoted material**, so every fence is removed before a bullet or a keyword is\nread; a pasted config that happens to list three steps is the user showing you\nsomething, not assigning it.\n\nWhat is left fires on one of three shapes: three or more enumerated items; two\nenumerated items plus a breadth or scope word; or a structural verb (`refactor`,\n`migrate`, `rename`, `rewrite`, `overhaul`, `backfill`, `scaffold`) together with\na breadth word (`every`, `each`, `across`, `throughout`, `codebase`,\n`call sites`, `multiple`, `several`, `all the`, `one by one`, `in parallel`)\n**and** several targets actually named — two or more files with extensions, or a\nquantified plural such as "every module" or "all the call sites". That last\nconjunct is the difference between work with independent pieces and ordinary\nEnglish about one function: "refactor `parseCsv` to handle multiple delimiters\nacross quoted fields" is one function in one file and does not fire. It would\nrather miss a multi-part task than become noise.\n\nOnce per session is enforced by an exclusive create of a marker file under the\nsystem temp directory, named by a hash of `session_id`. The exclusive create is\nthe lock, so two racing hooks cannot both speak. A session with no id, and a\nmarker that cannot be written, both mean silence rather than a hook that might\nspeak every turn. `BRIGADIER_NUDGE=off` silences it entirely, and so does\n`BRIGADIER_WORKER=1`, which brigadier stamps into every worker\'s environment: a\nslice prompt is long and full of exactly these words, and a worker must never be\ntold to run brigadier. That check is read before stdin is.\n\n## The contract both scripts implement\n\n```\nin    one JSON object on stdin\nout   one JSON object on stdout, or nothing at all\nexit  always 0\n```\n\n`handoff.mjs` answers `{"systemMessage": "<one sentence>"}`. `nudge.mjs` answers\nthe same sentence under two keys: `systemMessage`, so the user sees that\nbrigadier spoke, and `additionalContext`, which is the field the model actually\nreads. A nudge that only reached the human would not make the skill fire, which\nis the whole job.\n\nNothing about that contract is Claude-Code-specific, which is why `handoff.mjs`\nis shipped byte-for-byte under `surfaces/codex/hooks/` as well.\n\n## What they deliberately do not do\n\n- They do not block, veto, or rewrite anything. `UserPromptSubmit` can erase a\n  prompt by exiting 2. Neither script ever exits non-zero, so neither can.\n- They do not exit non-zero, ever. A hook that fails, fails inside somebody\n  else\'s session.\n- `handoff.mjs` does not walk a transcript larger than 8 MB, and neither script\n  waits longer than 2 seconds for stdin to end. `nudge.mjs` scans at most the\n  first 20,000 characters of a prompt. All three degrade to a weaker answer or to\n  silence rather than to a stall.\n\n## How other hosts differ\n\n- **Codex** — `brigadier install codex` registers `handoff.mjs` against\n  `PreCompact`, then Codex requires the user to approve it. The nudge is **not**\n  registered there: Codex binds hook approval to the registration, so adding an\n  event would silently disarm the approved handoff until the user approved again.\n  See `surfaces/codex/hooks/README.md`.\n- **Claude Desktop, Cursor, Windsurf, Antigravity** — impossible. None exposes a\n  hook surface, and an MCP server is called by the model rather than by the\n  transcript. Those hosts get the doctrine through MCP tool descriptions instead.\n- **opencode** — provided instead by `surfaces/opencode/plugin/brigadier.js`,\n  because opencode\'s seam is the plugin event bus rather than a hook process.\n',
    "claude-code/hooks/handoff.mjs":
      '#!/usr/bin/env node\n\n/**\n * The handoff hook.\n *\n * A host session that is about to run out of context is exactly the session most\n * tempted to keep grinding rather than delegate. This hook watches for that\n * moment and says the one sentence the doctrine exists to say: stop, write a\n * plan, hand it to `brigadier run`, and keep the review.\n *\n * THE CONTRACT, which is deliberately host-agnostic:\n *   in   one JSON object on stdin, optionally carrying `transcript_path`\n *   out  one JSON object on stdout: {"systemMessage": "<one sentence>"}\n *   exit always 0\n *\n * A hook that fails is worse than a hook that is absent, because it fails inside\n * somebody else\'s session. So every unhappy path here — unparseable stdin, a\n * missing transcript, an unreadable transcript, a transcript too large to walk —\n * degrades to a weaker message or to silence, and never to a non-zero exit.\n *\n * Zero dependencies, node: builtins only. It is copied verbatim into each host\'s\n * configuration directory by `brigadier install`, so it cannot import anything\n * from the brigadier tree either.\n */\n\nimport { readFileSync, statSync } from "node:fs";\n\n/** Beyond this, the transcript is not walked: a hook must not stall a session. */\nconst MAX_TRANSCRIPT_BYTES = 8_000_000;\n\n/** A hook whose stdin never ends would wedge the host. This is the escape. */\nconst DEFAULT_STDIN_TIMEOUT_MS = 2000;\n\nconst ADVICE =\n  "Do not carry the remaining work here — write it as a brigadier plan and run `brigadier run --plan <file>`. A fresh worker gets a clean context; you keep the review.";\n\nmain();\n\nfunction main() {\n  // A host that stops reading must not turn this hook into a failure; a gone\n  // pipe has no useful recovery, so swallow its write error.\n  process.stdout.on("error", () => {});\n  readStdin((raw) => {\n    const message = buildMessage(raw);\n    if (message !== null) {\n      process.stdout.write(`${JSON.stringify({ systemMessage: message })}\\n`);\n    }\n    process.exitCode = 0;\n  });\n}\n\n/**\n * Null means "say nothing", which is the right answer for input this hook does\n * not understand. Silence is always a legal hook response; a guess is not.\n */\nfunction buildMessage(raw) {\n  let payload;\n  try {\n    payload = JSON.parse(raw);\n  } catch {\n    return null;\n  }\n  if (\n    typeof payload !== "object" ||\n    payload === null ||\n    Array.isArray(payload)\n  ) {\n    return null;\n  }\n  const turns = countAssistantTurns(payload.transcript_path);\n  return turns === null\n    ? `brigadier: this session is out of context. ${ADVICE}`\n    : `brigadier: this session is out of context after ${turns} assistant turn(s). ${ADVICE}`;\n}\n\n/**\n * Claude Code assistant records and Codex assistant message response items are\n * counted; when neither shape appears, this returns null. An uncounted message\n * serves the caller better than a zero that may falsely describe an unfamiliar\n * transcript shape.\n */\nfunction countAssistantTurns(transcriptPath) {\n  if (typeof transcriptPath !== "string" || transcriptPath.length === 0) {\n    return null;\n  }\n  try {\n    const stats = statSync(transcriptPath);\n    if (!stats.isFile() || stats.size > MAX_TRANSCRIPT_BYTES) {\n      return null;\n    }\n    let claudeTurns = 0;\n    let codexTurns = 0;\n    for (const line of readFileSync(transcriptPath, "utf8").split("\\n")) {\n      if (line.length === 0) {\n        continue;\n      }\n      try {\n        const entry = JSON.parse(line);\n        if (entry.type === "assistant") {\n          claudeTurns += 1;\n        }\n        const payload = entry.payload;\n        if (\n          entry.type === "response_item" &&\n          typeof payload === "object" &&\n          payload !== null &&\n          payload.type === "message" &&\n          payload.role === "assistant"\n        ) {\n          codexTurns += 1;\n        }\n      } catch {\n        // A partially written transcript line is normal; skip it.\n      }\n    }\n    const turns = claudeTurns + codexTurns;\n    return turns === 0 ? null : turns;\n  } catch {\n    return null;\n  }\n}\n\n/**\n * Drains stdin, or gives up on it.\n *\n * THE TEARDOWN IS THE POINT, not the timeout. A host that writes the hook\'s\n * payload and then forgets to close the pipe leaves this process holding an open\n * read handle, and an open read handle keeps the event loop alive forever — so a\n * timeout that only *fired* would print the message and then hang anyway, which\n * is the exact failure the timeout existed to prevent. `finish` therefore stops\n * listening and releases the stream before it answers.\n */\nfunction readStdin(done) {\n  const timeoutMs = readTimeout();\n  let text = "";\n  let finished = false;\n  const onData = (chunk) => {\n    text += chunk;\n  };\n  const finish = () => {\n    if (finished) {\n      return;\n    }\n    finished = true;\n    clearTimeout(timer);\n    process.stdin.removeListener("data", onData);\n    process.stdin.pause();\n    process.stdin.unref?.();\n    done(text);\n  };\n  const timer = setTimeout(finish, timeoutMs);\n  timer.unref?.();\n  process.stdin.setEncoding("utf8");\n  process.stdin.on("data", onData);\n  process.stdin.on("end", finish);\n  process.stdin.on("error", finish);\n}\n\nfunction readTimeout() {\n  const raw = process.env.BRIGADIER_HANDOFF_STDIN_TIMEOUT_MS;\n  if (raw === undefined || !/^[0-9]+$/.test(raw)) {\n    return DEFAULT_STDIN_TIMEOUT_MS;\n  }\n  const parsed = Number(raw);\n  return Number.isSafeInteger(parsed) && parsed > 0\n    ? parsed\n    : DEFAULT_STDIN_TIMEOUT_MS;\n}\n',
    "claude-code/hooks/hooks.json":
      '{\n  "hooks": {\n    "PreCompact": [\n      {\n        "matcher": "*",\n        "hooks": [\n          {\n            "type": "command",\n            "command": "${CLAUDE_PLUGIN_ROOT}/hooks/handoff.mjs"\n          }\n        ]\n      }\n    ],\n    "UserPromptSubmit": [\n      {\n        "hooks": [\n          {\n            "type": "command",\n            "command": "${CLAUDE_PLUGIN_ROOT}/hooks/nudge.mjs"\n          }\n        ]\n      }\n    ]\n  }\n}\n',
    "claude-code/hooks/nudge.mjs":
      '#!/usr/bin/env node\n\n/**\n * The nudge hook.\n *\n * The brigadier skill only fires when the host model happens to notice its\n * description, which is exactly the wrong thing to depend on at the moment a\n * multi-part task arrives. This hook fires on the prompt itself and says one\n * sentence.\n *\n * THE DESIGN CONSTRAINT IS RESTRAINT, NOT COVERAGE. A hook that speaks every\n * turn gets uninstalled within a day, and an uninstalled hook nudges nobody. So\n * it is silent for an ordinary prompt, silent for a question, silent for\n * anything short, and silent for the whole rest of the session once it has\n * spoken. It would rather miss a multi-part task than become noise. Every\n * threshold below is tuned in that direction, and none of them should be\n * loosened without the same reasoning.\n *\n * THE CONTRACT, shared with `handoff.mjs`:\n *   in   one JSON object on stdin, carrying `session_id` and the prompt text\n *   out  one JSON object on stdout, or nothing at all\n *   exit always 0\n *\n * A BRIGADIER WORKER NEVER HEARS THIS. brigadier stamps `BRIGADIER_WORKER=1`\n * into every worker\'s environment, and a slice prompt is long, enumerated, and\n * full of exactly the words this hook looks for — so without that check the hook\n * would tell a worker to start a second orchestrator from inside its own slice.\n * It is read before stdin is, because it is the cheapest and least breakable\n * place to answer a question that cannot depend on the payload.\n *\n * The object carries the same sentence twice, deliberately. `systemMessage` is\n * shown to the user, so the nudge is never something that happened behind their\n * back. `additionalContext` is what the model actually reads — a hook that only\n * spoke to the human would not make the skill fire, which is the entire job.\n *\n * Zero dependencies, node: builtins only. It is copied verbatim into the host\'s\n * configuration directory by `brigadier install`, so it cannot import anything\n * from the brigadier tree either.\n */\n\nimport { createHash } from "node:crypto";\nimport { mkdirSync, writeFileSync } from "node:fs";\nimport { tmpdir } from "node:os";\nimport { join } from "node:path";\n\n/** Below this, a prompt is a request, not a plan. */\nconst MINIMUM_PROMPT_CHARACTERS = 120;\n\n/** Only the head of a prompt is scanned: a pasted log must not cost a session. */\nconst MAX_SCANNED_CHARACTERS = 20_000;\n\n/** A hook whose stdin never ends would wedge the host. This is the escape. */\nconst DEFAULT_STDIN_TIMEOUT_MS = 2000;\n\n/** Where the once-per-session marker lives, under the system temp directory. */\nconst MARKER_DIRECTORY_NAME = "brigadier-nudge";\n\nconst MESSAGE =\n  "brigadier: this looks like more than one independent piece of work. Load the brigadier skill, write it as a plan, and run `brigadier run` from here rather than doing it inline. If you are already a brigadier worker running one slice, ignore this and do your slice.";\n\n/**\n * Work that is genuinely spread out. Deliberately narrow: a word that shows up\n * in ordinary conversation about one file does not belong in this list.\n */\nconst BREADTH_MARKERS = [\n  /\\ball (?:of )?the\\b/i,\n  /\\bevery\\b/i,\n  /\\beach\\b/i,\n  /\\bacross\\b/i,\n  /\\bthroughout\\b/i,\n  /\\bcodebase\\b/i,\n  /\\bcall sites?\\b/i,\n  /\\bone by one\\b/i,\n  /\\bin parallel\\b/i,\n  /\\bmultiple\\b/i,\n  /\\bseveral\\b/i,\n];\n\n/** Work that is structurally large. A verb, not a topic. */\nconst SCOPE_MARKERS = [\n  /\\brefactor/i,\n  /\\bmigrat(?:e|es|ing|ion)\\b/i,\n  /\\brenam(?:e|es|ing)\\b/i,\n  /\\brewrit(?:e|es|ing)\\b/i,\n  /\\boverhaul\\b/i,\n  /\\bbackfill\\b/i,\n  /\\bscaffold/i,\n];\n\n/**\n * Several distinct targets, actually named: two or more files with extensions,\n * or a quantified plural noun such as "every module" or "all the call sites".\n * This is the difference between work that has independent pieces and work that\n * merely uses a big verb — "refactor `parseCsv` to handle multiple delimiters"\n * is one function in one file, and it matches neither of these.\n */\nconst NAMED_FILE =\n  /\\b[\\w./-]*\\w\\.(?:ts|tsx|js|jsx|mjs|cjs|json|md|py|go|rs|rb|java|kt|swift|c|h|cc|cpp|cs|php|sql|css|scss|html|htm|yml|yaml|toml|sh)\\b/gi;\nconst QUANTIFIED_PLURAL =\n  /\\b(?:all (?:of )?the|every|each|both|multiple|several|many)\\s+(?:\\w+[\\s-]+){0,2}(?:files?|modules?|packages?|services?|components?|handlers?|endpoints?|routes?|call ?sites?|callers?|tests?|specs?|scripts?|commands?|screens?|pages?|migrations?|queries?|adapters?|providers?|consumers?|usages?|references?|imports?|directories?|folders?|repos?|repositories?|places?|sites?)\\b/i;\n\n/**\n * A prompt that opens with one of these and carries a question mark is asking,\n * not assigning — however many bullet points of symptoms it goes on to list.\n */\nconst QUESTION_OPENERS =\n  /^(?:can|could|would|will|shall|should|do|does|did|is|are|was|were|has|have|am|may|might|why|what|when|where|which|who|whom|whose|how)\\b/i;\n\n/** A fenced block, terminated or not. Quoted material, never an instruction. */\nconst FENCED_BLOCK = /```[\\s\\S]*?```/g;\nconst UNTERMINATED_FENCE = /```[\\s\\S]*$/;\n\n/** `- item`, `* item`, `1. item`, `2) item`. */\nconst ENUMERATION = /^\\s*(?:[-*+]\\s+|\\d+[.)]\\s+)\\S/;\n\nmain();\n\nfunction main() {\n  // A host that stops reading must not turn this hook into a failure; a gone\n  // pipe has no useful recovery, so swallow its write error.\n  process.stdout.on("error", () => {});\n  // FIRST, AND BEFORE STDIN IS EVEN READ. A worker must never be told to run\n  // brigadier; see the header. `workerEnvironment` in src/worker/shared.ts is\n  // what stamps this, at the spawn, so it cannot be inherited into a genuine\n  // top-level session from an ancestor.\n  if (process.env.BRIGADIER_WORKER === "1") {\n    process.exitCode = 0;\n    return;\n  }\n  readStdin((raw) => {\n    if (shouldNudge(raw)) {\n      process.stdout.write(\n        `${JSON.stringify({\n          systemMessage: MESSAGE,\n          additionalContext: MESSAGE,\n        })}\\n`,\n      );\n    }\n    process.exitCode = 0;\n  });\n}\n\n/**\n * Every unrecognised, unbounded, or already-spent case answers false. Silence is\n * always a legal hook response, and it is the right one whenever this hook is\n * not certain of all three of: the event, the prompt, and the session.\n */\nfunction shouldNudge(raw) {\n  if (process.env.BRIGADIER_NUDGE === "off") {\n    return false;\n  }\n  let payload;\n  try {\n    payload = JSON.parse(raw);\n  } catch {\n    return false;\n  }\n  if (\n    typeof payload !== "object" ||\n    payload === null ||\n    Array.isArray(payload)\n  ) {\n    return false;\n  }\n  if (payload.hook_event_name !== "UserPromptSubmit") {\n    return false;\n  }\n  // `user_input` is the current field name; `prompt` is what older Claude Code\n  // builds sent. Reading both costs one line and survives either.\n  const text =\n    typeof payload.user_input === "string"\n      ? payload.user_input\n      : typeof payload.prompt === "string"\n        ? payload.prompt\n        : null;\n  if (text === null || !looksMultiPart(text)) {\n    return false;\n  }\n  return claimSession(payload.session_id);\n}\n\n/**\n * True only for a prompt that describes work in more than one independent piece.\n *\n * THE TWO REFUSALS COME FIRST, and neither can be argued out of by anything\n * later in the prompt.\n *\n *   A QUESTION IS NEVER ENOUGH — a bug report that opens "why is this failing?"\n *   and then lists three symptoms is three bullet points about ONE thing, so the\n *   question test runs before the list is even counted.\n *\n *   A FENCE IS QUOTED MATERIAL — a pasted config or diff can carry bullets, big\n *   verbs, and plural nouns that the user is showing rather than assigning, so\n *   every fenced block is removed before anything is counted.\n *\n * What is left accepts three shapes: a real list of three; a short list plus a\n * reason to believe it is spread out; or a structural verb AND a breadth word\n * AND several targets actually named. That last conjunct is the one that keeps\n * ordinary English about one function — "refactor `parseCsv` to handle multiple\n * delimiters across quoted fields" — from spending the session\'s only nudge.\n */\nfunction looksMultiPart(text) {\n  const trimmed = text.trim().slice(0, MAX_SCANNED_CHARACTERS);\n  if (trimmed.length < MINIMUM_PROMPT_CHARACTERS) {\n    return false;\n  }\n  if (looksLikeQuestion(trimmed)) {\n    return false;\n  }\n  const prose = trimmed\n    .replace(FENCED_BLOCK, "\\n")\n    .replace(UNTERMINATED_FENCE, "\\n");\n  const enumerated = prose\n    .split("\\n")\n    .filter((line) => ENUMERATION.test(line)).length;\n  if (enumerated >= 3) {\n    return true;\n  }\n  const breadth = BREADTH_MARKERS.some((marker) => marker.test(prose));\n  const scope = SCOPE_MARKERS.some((marker) => marker.test(prose));\n  if (enumerated >= 2 && (breadth || scope)) {\n    return true;\n  }\n  return breadth && scope && namesSeveralTargets(prose);\n}\n\n/**\n * Whether this prompt reads as a question rather than an assignment.\n *\n * A trailing `?` is the easy case. The other one is a prompt whose OPENING\n * sentence is the question and whose remainder is evidence — symptoms, a log,\n * a list of things the asker has already tried — which is the shape a bug\n * report takes and is exactly the shape that used to slip through.\n */\nfunction looksLikeQuestion(text) {\n  if (text.endsWith("?")) {\n    return true;\n  }\n  const mark = text.indexOf("?");\n  if (mark < 0) {\n    return false;\n  }\n  const sentenceEnd = text.search(/[.!]/);\n  return sentenceEnd < 0 || mark < sentenceEnd || QUESTION_OPENERS.test(text);\n}\n\n/** Two or more named files, or one quantified plural target. */\nfunction namesSeveralTargets(text) {\n  if (QUANTIFIED_PLURAL.test(text)) {\n    return true;\n  }\n  const files = text.match(NAMED_FILE);\n  return files !== null && new Set(files).size >= 2;\n}\n\n/**\n * Records that this session has been nudged, and answers whether this call is\n * the one that got there first.\n *\n * The exclusive create IS the lock: two hooks racing on the same session cannot\n * both succeed. A session with no id cannot be bounded, and a marker that cannot\n * be written cannot bound anything either, so both answer false rather than risk\n * a hook that speaks on every turn.\n */\nfunction claimSession(sessionId) {\n  if (typeof sessionId !== "string" || sessionId.length === 0) {\n    return false;\n  }\n  // Hashed, not interpolated: a session id is host-supplied and must never\n  // become a path segment.\n  const marker = join(\n    tmpdir(),\n    MARKER_DIRECTORY_NAME,\n    createHash("sha256").update(sessionId, "utf8").digest("hex").slice(0, 32),\n  );\n  try {\n    mkdirSync(join(tmpdir(), MARKER_DIRECTORY_NAME), {\n      recursive: true,\n      mode: 0o700,\n    });\n    writeFileSync(marker, "", { flag: "wx", mode: 0o600 });\n    return true;\n  } catch {\n    return false;\n  }\n}\n\n/**\n * Drains stdin, or gives up on it.\n *\n * THE TEARDOWN IS THE POINT, not the timeout. A host that writes the hook\'s\n * payload and then forgets to close the pipe leaves this process holding an open\n * read handle, and an open read handle keeps the event loop alive forever — so a\n * timeout that only *fired* would print the message and then hang anyway, which\n * is the exact failure the timeout existed to prevent. `finish` therefore stops\n * listening and releases the stream before it answers.\n */\nfunction readStdin(done) {\n  const timeoutMs = readTimeout();\n  let text = "";\n  let finished = false;\n  const onData = (chunk) => {\n    text += chunk;\n  };\n  const finish = () => {\n    if (finished) {\n      return;\n    }\n    finished = true;\n    clearTimeout(timer);\n    process.stdin.removeListener("data", onData);\n    process.stdin.pause();\n    process.stdin.unref?.();\n    done(text);\n  };\n  const timer = setTimeout(finish, timeoutMs);\n  timer.unref?.();\n  process.stdin.setEncoding("utf8");\n  process.stdin.on("data", onData);\n  process.stdin.on("end", finish);\n  process.stdin.on("error", finish);\n}\n\nfunction readTimeout() {\n  const raw = process.env.BRIGADIER_HANDOFF_STDIN_TIMEOUT_MS;\n  if (raw === undefined || !/^[0-9]+$/.test(raw)) {\n    return DEFAULT_STDIN_TIMEOUT_MS;\n  }\n  const parsed = Number(raw);\n  return Number.isSafeInteger(parsed) && parsed > 0\n    ? parsed\n    : DEFAULT_STDIN_TIMEOUT_MS;\n}\n',
    "claude-desktop/README.md":
      "# The Claude Desktop surface\n\n**Status: MCP server. No skill, and no handoff hook — neither is possible here.**\n\n## Why Desktop gets a different artifact from every other host\n\nDesktop **Skills execute server-side**. They run in Anthropic's infrastructure,\nnot on your laptop, so a skill cannot invoke `brigadier`, cannot see your\nrepository, and cannot spawn `claude -p`. Installing the doctrine as a Desktop\nskill would produce a model that has been told to delegate and has nothing to\ndelegate to.\n\nDesktop **MCP servers run locally, with your full user privileges**. They can\nspawn `claude -p`, read your working tree, and start a real run. That asymmetry\nis the entire reason brigadier ships an MCP server (`src/mcp/server.ts`), and the\nreason Desktop is the one host where the tiny doctrine file is not the answer.\n\n## The handoff hook does not exist here\n\nThe transcript-watching handoff works on Claude Code. On\nopencode, its event names were verified only on 1.18.16, without triggering live\ncompaction, and remain version-dependent. On Codex, brigadier registers it and\nCodex trust-gates the registration; approval remains valid if the script at that\npath changes. On Desktop it is **impossible**, not merely unimplemented:\nDesktop exposes no hook surface of any kind, and an MCP server is invoked by the\nmodel when the model chooses to invoke it — never by the transcript, and never at\nthe moment the context fills. There is no workaround and none is offered.\n\n## Installing: the registration, or the bundle\n\n`brigadier install claude-desktop` does two things.\n\nIt merges a `brigadier` entry into Desktop's own MCP configuration at\n`~/Library/Application Support/Claude/claude_desktop_config.json`, under the\ntop-level `mcpServers` key documented at\n<https://modelcontextprotocol.io/docs/develop/connect-local-servers>. Every other\nserver in that file is preserved byte-for-byte; only brigadier's own key is\nwritten. **This happens only if you consented once during `brigadier init`**, and\nonly if Desktop's configuration directory already exists. Quit Desktop\ncompletely and relaunch it before the server appears. This is the path that\nneeds no build step.\n\nIt also stages this directory to `~/.brigadier/surfaces/claude-desktop/` and\nprints what to do next, for anyone who wants the packaged `.mcpb` extension\ninstead. brigadier does not install that bundle: Desktop installs a bundle by an\nexplicit user action and brigadier does not forge those.\n\nTo produce the installable `.mcpb`:\n\n1. `bun run build:mcp` — emits `dist/mcp/server.js`; it does not populate the\n   staged bundle.\n2. Copy that output into the staged directory as `server/brigadier-mcp.js`, the\n   path named by `manifest.json`.\n3. Zip the staged directory with `manifest.json` at the archive root and rename\n   it `brigadier.mcpb`.\n4. Open it with Claude Desktop, or drop it into Desktop's extensions pane.\n\nThe server is zero-dependency: it speaks JSON-RPC 2.0 over stdio against the MCP\nspec directly, with no SDK. There is nothing to `npm install` inside the bundle.\n\n## The tool surface\n\nThree tools, and they are exactly what brigadier can do today — no more:\n\n| Tool | Effect |\n| --- | --- |\n| `brigadier_validate_plan` | Pure. Shape defects, scheduling defects, and the dependency waves a plan would run in. |\n| `brigadier_route_plan` | Reads this machine's config. Reports the vendor, model, and effort each slice would get, or why nothing can take it. Creates no worktree, spawns no worker. |\n| `brigadier_run` | The real thing: worktrees, workers, commits, one integration branch. |\n\nThe `tools` array in `manifest.json` must name exactly these three;\n`test/mcp.test.ts` fails if the manifest and the server ever disagree.\n",
    "claude-desktop/manifest.json":
      '{\n  "manifest_version": "0.2",\n  "name": "brigadier",\n  "display_name": "brigadier",\n  "version": "0.1.1",\n  "description": "Hand coding work to the brigadier CLI running locally on this machine.",\n  "long_description": "Claude Desktop Skills execute server-side and cannot invoke a binary on your laptop. Desktop MCP servers run locally with full user privileges and can spawn `claude -p`. That is why brigadier reaches Desktop as an MCP server rather than as a skill: it is the only surface that can actually start a run.",\n  "author": {\n    "name": "brigadier"\n  },\n  "server": {\n    "type": "node",\n    "entry_point": "server/brigadier-mcp.js",\n    "mcp_config": {\n      "command": "node",\n      "args": ["${__dirname}/server/brigadier-mcp.js"]\n    }\n  },\n  "tools": [\n    {\n      "name": "brigadier_validate_plan",\n      "description": "Check a brigadier plan document for shape defects and scheduling defects, and report the dependency waves it would run in. Touches nothing. Draft a plan against this before brigadier_run: it names every defect at once, including two slices that claim the same path."\n    },\n    {\n      "name": "brigadier_route_plan",\n      "description": "Report which vendor, model, and effort this machine would give each slice of a plan, or why no model can take it. Creates no worktree and spawns no worker. Worth a call before brigadier_run, because a slice no model can take is worth knowing about before a worker is spent on its siblings."\n    },\n    {\n      "name": "brigadier_run",\n      "description": "Hand multi-part coding work to brigadier instead of doing it inline: it routes every slice, gives each its own git worktree and worker, commits what each produced, and merges the lot. Reach for this whenever the work has more than one independent piece — a feature, a cross-file refactor, a migration, a bug with several call sites, a batch of mechanical edits — and route that work here rather than editing the files yourself. Build the plan as the plan argument documents: one slice per independent piece, exclusive ownedPaths (no two slices may claim the same path, or a directory containing another\'s), and dependsOn naming any slice whose committed output another slice needs. Never call this if you are yourself a brigadier worker running one slice: re-entry spends the whole slice and lands nothing."\n    }\n  ],\n  "tools_generated": false,\n  "keywords": ["brigadier", "orchestration", "delegation", "coding"],\n  "compatibility": {\n    "runtimes": {\n      "node": ">=20.0.0"\n    }\n  }\n}\n',
    "codex/AGENTS.md":
      '# You are not the worker\n\nThis machine has `brigadier` installed, and you are the one who runs it. When a\ncoding task decomposes into independent pieces, do not write them here. Plan\nthem, invoke `brigadier run` yourself from inside this session, and review what\ncomes back. Your context is for coordination and judgement; a worker session is\ndisposable and starts clean.\n\n## If you are already a brigadier worker, stop here\n\n**A brigadier worker must never invoke brigadier.** If the prompt you were given\nis one slice of somebody else\'s plan — it names an `id`, the paths you own, and\nthe evidence you owe — then you are the worker, and the work in front of you is\nthe work you do. Spawning a second orchestrator from inside a slice spends the\nwhole slice and lands nothing. This has happened. brigadier stamps\n`BRIGADIER_WORKER=1` into every worker\'s environment, which is enough to keep the\nnudge hook quiet inside a worker but does not stop you: nothing in the product\nrefuses a second run, so this paragraph is what prevents it. This file is loaded\ninto brigadier\'s own workers, so it is talking to you.\n\n1. **Decompose by file ownership.** Disjoint `ownedPaths` are necessary, but do\n   not by themselves make slices independent. If one slice needs another\'s\n   committed output, declare that real dependency in `dependsOn`. Dependencies\n   place work in later serial waves; independent slices share a wave and can run\n   concurrently, up to `--max-workers`.\n2. **Write a plan document** (JSON). Every slice needs `id`, `title`, `prompt`,\n   `ownedPaths`, and `difficulty` (`routine`, `standard`, or `hard` — there is no\n   default). `requires` is optional. `dependsOn` names prerequisite slice ids.\n   brigadier reconciles each non-final dependency wave before creating the next\n   wave\'s worktrees, so dependent slices start from their prerequisites\' committed\n   output. Unknown ids, self-dependencies, and cycles are refused.\n\n   ```json\n   {\n     "id": "add-retry",\n     "goal": "Retry transient HTTP failures in the client",\n     "slices": [\n       {\n         "id": "retry-core",\n         "title": "Retry loop and backoff",\n         "prompt": "One self-contained brief: interfaces, constraints, definition of done, evidence required.",\n         "ownedPaths": ["src/http/retry.ts"],\n         "difficulty": "standard"\n       }\n     ]\n   }\n   ```\n\n3. **Dry-run first:** `brigadier run --plan plan.json --dry-run` routes every\n   slice and reports it, creating no worktree and spawning nothing. Add\n   `--verbose` to see which vendor, model, and effort would take each slice.\n4. **Run it:** `brigadier run --plan plan.json --max-workers 3`. Each slice gets\n   its own worktree and branch; what lands is merged onto one integration branch.\n5. **Review the diffs yourself.** A worker\'s report is a claim, not evidence.\n\n## Do not\n\n- Edit a file while a slice that owns it is running.\n- Do the work here because it "looks quick" — a one-file change is a one-slice\n  plan.\n- Hand the user a command to type. You have a shell; run `brigadier` yourself.\n- Invent commands. brigadier has exactly four: `run`, `install`, `mcp`, and\n  `init`. `brigadier run "<task description>"` asks a model to decompose the task\n  and sends the result through the same validator used for `--plan`. On genuine\n  ambiguity it exits 4 with `status: "needs_human"` and structured questions; no\n  worktree is created and no slice worker is spawned.\n\nThere is no setup step. Configuration is automatic: `brigadier run` probes this\nmachine, writes `$BRIGADIER_HOME/config.json` (default `~/.brigadier/config.json`)\nwhen none is there, and carries on. Never run `brigadier init` to make a config\nappear; it is not a prerequisite. Its one real job belongs to a human: recording\nthe explicit yes that lets brigadier register its MCP server into a GUI\napplication\'s own configuration. If `brigadier install` reports a registration\nskipped for want of consent, pass that sentence to the user and let them run\n`brigadier init` once themselves.\n\n## A note specific to Codex\n\nbrigadier drives `codex` as a plain subprocess and passes\n`project_doc_max_bytes=0` or `--ignore-user-config` when a slice asks for\ninstruction isolation. Codex 0.145.0 loads `$CODEX_HOME/AGENTS.md` — this file —\nregardless of either flag, and exposes no way to suppress it. So this file is\nread by brigadier\'s own workers too. Keep it short, keep it doctrine, and put\nnothing in it that a worker running one slice should not see.\n',
    "codex/hooks/README.md":
      '# The handoff hook on Codex\n\n**Status: registered by brigadier, then trust-gated by Codex.**\n\n`brigadier install codex` registers the hook, but registration is not approval.\nCodex will not run a hook it has not been told to trust. Approving one is a\nmanual, interactive click in Codex. Approval is bound to the registration — the\nevent, matcher, and command configuration — not to the contents of\n`handoff.mjs`. The script at that approved path can later change without Codex\nasking again. To re-review an edited script, deliberately change the registration\nand approve the new registration.\n\nOn Claude Code the same hook installs with no click at all. That asymmetry is\nreal, and it is the reason this file exists rather than a line in a table.\n\n## The contract `handoff.mjs` implements\n\n```\nin    one JSON object on stdin, optionally carrying `transcript_path`\nout   one JSON object on stdout: {"systemMessage": "<one sentence>"}\nexit  always 0\n```\n\nThis file is byte-for-byte identical to\n`surfaces/claude-code/hooks/handoff.mjs`, and a test enforces that. Codex 0.145.0\nsends `transcript_path` in the `PreCompact` payload, which is exactly what the\nscript reads.\n\n## What brigadier registers\n\nThe installer copies the script to the absolute form of\n`~/.agents/skills/brigadier/hooks/handoff.mjs`, then merges this entry into\n`$CODEX_HOME/hooks.json` (default `~/.codex/hooks.json`):\n\n```json\n{\n  "hooks": {\n    "PreCompact": [\n      {\n        "hooks": [\n          {\n            "type": "command",\n            "command": "\'<absolute path>/.agents/skills/brigadier/hooks/handoff.mjs\' # brigadier-managed-hook"\n          }\n        ]\n      }\n    ]\n  }\n}\n```\n\n`PreCompact` is the only event brigadier registers here, and that is deliberate.\nClaude Code also gets a `UserPromptSubmit` nudge; Codex does not, because Codex\nbinds approval to the registration — event, matcher, and command together — so\nadding a second event would disarm the already-approved handoff until the user\napproved the new registration. A nudge is not worth silently switching off the\nhandoff.\n\n`PreCompact` is the Codex event fired before compaction. The command path is\nabsolute and shell-quoted. `# brigadier-managed-hook` is the stable ownership\nmarker, but an entry is brigadier-owned only when it has no keys other than a\n`hooks` array containing exactly one `{ "type": "command", "command": "..." }`\nhook whose command ends with that marker. A marked hook with siblings, a matcher,\nor any other shape is foreign: brigadier preserves it and appends its own entry,\neven if that leaves the marker visible twice. All other events, entries, and\nunknown keys in the shared file are preserved. Malformed JSON is refused and\nleft byte-for-byte unchanged.\n\n## Approval is still required\n\nStart an interactive Codex session and approve the hook when Codex presents its\nhook-trust prompt. Until that approval is persisted, the hook is a silent no-op:\nCodex still exits 0, with no warning and no hook output. That persisted approval\nremains valid when `handoff.mjs` changes. Only changing the registration itself —\nthe command string, event, or matcher — re-arms the prompt. To re-review an\nedited script, deliberately change the registration and approve it again.\n\nFor vetted automation only, `codex exec --dangerously-bypass-hook-trust` runs\nenabled hooks for that invocation without persisted trust. The name is\naccurate: it bypasses the trust check for every enabled hook in that invocation,\nnot only brigadier\'s. Use it only when the automation has already vetted every\nhook source. It does not persist approval.\n',
    "codex/hooks/handoff.mjs":
      '#!/usr/bin/env node\n\n/**\n * The handoff hook.\n *\n * A host session that is about to run out of context is exactly the session most\n * tempted to keep grinding rather than delegate. This hook watches for that\n * moment and says the one sentence the doctrine exists to say: stop, write a\n * plan, hand it to `brigadier run`, and keep the review.\n *\n * THE CONTRACT, which is deliberately host-agnostic:\n *   in   one JSON object on stdin, optionally carrying `transcript_path`\n *   out  one JSON object on stdout: {"systemMessage": "<one sentence>"}\n *   exit always 0\n *\n * A hook that fails is worse than a hook that is absent, because it fails inside\n * somebody else\'s session. So every unhappy path here — unparseable stdin, a\n * missing transcript, an unreadable transcript, a transcript too large to walk —\n * degrades to a weaker message or to silence, and never to a non-zero exit.\n *\n * Zero dependencies, node: builtins only. It is copied verbatim into each host\'s\n * configuration directory by `brigadier install`, so it cannot import anything\n * from the brigadier tree either.\n */\n\nimport { readFileSync, statSync } from "node:fs";\n\n/** Beyond this, the transcript is not walked: a hook must not stall a session. */\nconst MAX_TRANSCRIPT_BYTES = 8_000_000;\n\n/** A hook whose stdin never ends would wedge the host. This is the escape. */\nconst DEFAULT_STDIN_TIMEOUT_MS = 2000;\n\nconst ADVICE =\n  "Do not carry the remaining work here — write it as a brigadier plan and run `brigadier run --plan <file>`. A fresh worker gets a clean context; you keep the review.";\n\nmain();\n\nfunction main() {\n  // A host that stops reading must not turn this hook into a failure; a gone\n  // pipe has no useful recovery, so swallow its write error.\n  process.stdout.on("error", () => {});\n  readStdin((raw) => {\n    const message = buildMessage(raw);\n    if (message !== null) {\n      process.stdout.write(`${JSON.stringify({ systemMessage: message })}\\n`);\n    }\n    process.exitCode = 0;\n  });\n}\n\n/**\n * Null means "say nothing", which is the right answer for input this hook does\n * not understand. Silence is always a legal hook response; a guess is not.\n */\nfunction buildMessage(raw) {\n  let payload;\n  try {\n    payload = JSON.parse(raw);\n  } catch {\n    return null;\n  }\n  if (\n    typeof payload !== "object" ||\n    payload === null ||\n    Array.isArray(payload)\n  ) {\n    return null;\n  }\n  const turns = countAssistantTurns(payload.transcript_path);\n  return turns === null\n    ? `brigadier: this session is out of context. ${ADVICE}`\n    : `brigadier: this session is out of context after ${turns} assistant turn(s). ${ADVICE}`;\n}\n\n/**\n * Claude Code assistant records and Codex assistant message response items are\n * counted; when neither shape appears, this returns null. An uncounted message\n * serves the caller better than a zero that may falsely describe an unfamiliar\n * transcript shape.\n */\nfunction countAssistantTurns(transcriptPath) {\n  if (typeof transcriptPath !== "string" || transcriptPath.length === 0) {\n    return null;\n  }\n  try {\n    const stats = statSync(transcriptPath);\n    if (!stats.isFile() || stats.size > MAX_TRANSCRIPT_BYTES) {\n      return null;\n    }\n    let claudeTurns = 0;\n    let codexTurns = 0;\n    for (const line of readFileSync(transcriptPath, "utf8").split("\\n")) {\n      if (line.length === 0) {\n        continue;\n      }\n      try {\n        const entry = JSON.parse(line);\n        if (entry.type === "assistant") {\n          claudeTurns += 1;\n        }\n        const payload = entry.payload;\n        if (\n          entry.type === "response_item" &&\n          typeof payload === "object" &&\n          payload !== null &&\n          payload.type === "message" &&\n          payload.role === "assistant"\n        ) {\n          codexTurns += 1;\n        }\n      } catch {\n        // A partially written transcript line is normal; skip it.\n      }\n    }\n    const turns = claudeTurns + codexTurns;\n    return turns === 0 ? null : turns;\n  } catch {\n    return null;\n  }\n}\n\n/**\n * Drains stdin, or gives up on it.\n *\n * THE TEARDOWN IS THE POINT, not the timeout. A host that writes the hook\'s\n * payload and then forgets to close the pipe leaves this process holding an open\n * read handle, and an open read handle keeps the event loop alive forever — so a\n * timeout that only *fired* would print the message and then hang anyway, which\n * is the exact failure the timeout existed to prevent. `finish` therefore stops\n * listening and releases the stream before it answers.\n */\nfunction readStdin(done) {\n  const timeoutMs = readTimeout();\n  let text = "";\n  let finished = false;\n  const onData = (chunk) => {\n    text += chunk;\n  };\n  const finish = () => {\n    if (finished) {\n      return;\n    }\n    finished = true;\n    clearTimeout(timer);\n    process.stdin.removeListener("data", onData);\n    process.stdin.pause();\n    process.stdin.unref?.();\n    done(text);\n  };\n  const timer = setTimeout(finish, timeoutMs);\n  timer.unref?.();\n  process.stdin.setEncoding("utf8");\n  process.stdin.on("data", onData);\n  process.stdin.on("end", finish);\n  process.stdin.on("error", finish);\n}\n\nfunction readTimeout() {\n  const raw = process.env.BRIGADIER_HANDOFF_STDIN_TIMEOUT_MS;\n  if (raw === undefined || !/^[0-9]+$/.test(raw)) {\n    return DEFAULT_STDIN_TIMEOUT_MS;\n  }\n  const parsed = Number(raw);\n  return Number.isSafeInteger(parsed) && parsed > 0\n    ? parsed\n    : DEFAULT_STDIN_TIMEOUT_MS;\n}\n',
    "codex/skills/brigadier/SKILL.md":
      '---\nname: brigadier\ndescription: Load before starting any coding task with more than one independent piece of work — a feature, a cross-file refactor, a migration, a bug with several call sites, a batch of mechanical edits. Routes the work to the brigadier CLI instead of doing it in this session.\n---\n\n# You are not the worker\n\nThis machine has `brigadier` installed, and you are the one who runs it. When a\ntask decomposes into independent pieces, you do not write them here. You plan\nthem, invoke `brigadier run` yourself from inside this session, and review what\ncomes back. Your context is for coordination and judgement; a worker session is\ndisposable and starts clean.\n\n## If you are already a brigadier worker, stop here\n\n**A brigadier worker must never invoke brigadier.** If the prompt you were given\nis one slice of somebody else\'s plan — it names an `id`, the paths you own, and\nthe evidence you owe — then you are the worker, and the work in front of you is\nthe work you do. Spawning a second orchestrator from inside a slice spends the\nwhole slice and lands nothing. This has happened. brigadier stamps\n`BRIGADIER_WORKER=1` into every worker\'s environment, which is enough to keep the\nnudge hook quiet inside a worker but does not stop you: nothing in the product\nrefuses a second run, so this paragraph is what prevents it.\n\n## What to do\n\n1. **Decompose.** Disjoint `ownedPaths` are necessary, but they do not by\n   themselves make slices independent. If one slice needs another\'s committed\n   output, declare that real dependency in `dependsOn`. Dependencies place work\n   in later serial waves; independent slices share a wave and can run\n   concurrently, up to `--max-workers`. Partition by file ownership, not by\n   topic.\n2. **Write a plan document** (JSON):\n\n   ```json\n   {\n     "id": "add-retry",\n     "goal": "Retry transient HTTP failures in the client",\n     "slices": [\n       {\n         "id": "retry-core",\n         "title": "Retry loop and backoff",\n         "prompt": "One self-contained brief: the interfaces, the constraints, the definition of done, and the evidence required.",\n         "ownedPaths": ["src/http/retry.ts"],\n         "difficulty": "standard"\n       }\n     ]\n   }\n   ```\n\n   `id`, `title`, `prompt`, `ownedPaths` and `difficulty` are required on every\n   slice. `difficulty` is one of `routine`, `standard`, `hard`, and it has no\n   default: a plan that does not say how hard a slice is has not been planned.\n   `dependsOn` is optional and names prerequisite slice ids. brigadier runs\n   dependency waves in order and reconciles each non-final wave before creating\n   the next wave\'s worktrees, so dependent slices start from their prerequisites\'\n   committed output. Unknown ids, self-dependencies, and cycles are refused.\n   `requires` is optional and takes `imageInput`, `webSearch`,\n   `structuredOutput`, `commandExecution`, and `minContextWindowTokens`.\n3. **Dry-run it first.** `brigadier run --plan plan.json --dry-run` routes every\n   slice and reports it, without creating a worktree or spawning anything. Add\n   `--verbose` to see which vendor, model and effort would take each slice. A\n   slice that cannot route is worth knowing about before a worker is spent on\n   its siblings.\n4. **Run it.** `brigadier run --plan plan.json --max-workers 3`. Each slice gets\n   its own git worktree and its own branch; what lands is merged onto one\n   integration branch.\n5. **Review the diffs.** You own the outcome. A worker\'s report is a claim, not\n   evidence.\n\n## What not to do\n\n- Do not edit a file while a slice that owns it is running.\n- Do not do the work yourself because it "looks quick". A one-file change is a\n  one-slice plan, and writing the plan costs less than the context you spend\n  doing it here.\n- Do not hand the user a command to type. You have a shell; run `brigadier`\n  yourself and report what it did.\n- Do not invent commands. brigadier has exactly four: `run`, `install`, `mcp`,\n  and `init`. `brigadier run "<task description>"` asks a model to decompose the\n  task, then sends the result through the same validator used for `--plan`. On\n  genuine ambiguity it exits 4 with `status: "needs_human"` and structured\n  questions; no worktree is created and no slice worker is spawned.\n\n## There is no setup step\n\nConfiguration is automatic. `brigadier run` probes this machine for installed\nworker CLIs, writes `$BRIGADIER_HOME/config.json` — `~/.brigadier/config.json` by\ndefault — when none is there, and carries on. Never run `brigadier init` to make\na config appear: it has never been a prerequisite for a run, and a turn spent on\nit is a turn wasted. The one exception is not yours to take. Registering\nbrigadier\'s MCP server into a GUI application\'s own configuration takes a human\'s\nexplicit yes, and only the interactive question can ask for it — so if\n`brigadier install` reports a registration skipped for want of consent, pass that\nsentence to the user and let them run `brigadier init` once themselves.\n\n## Exit codes worth branching on\n\n`0` succeeded · `1` setup or planning failed, or the runner threw before returning\na report · `2` usage error · `3` a run report says the run failed, including\nschedulability or routing failures that created no worktree · `4` the planner needs\nhuman input (questions were printed; no slice worker, ref, or worktree was created)\n· `130`/`143` interrupted.\n',
    "opencode/README.md":
      "# The opencode surface\n\n**Status: plugin and event names verified on opencode 1.18.16; no live\ncompaction was triggered.**\n\nopencode reads `~/.claude/skills/` natively — the same directory Claude Code\nreads — and also reads `~/.agents/skills/`. So the doctrine is already installed\non an opencode machine the moment you run either of:\n\n```sh\nbrigadier install claude-code   # writes ~/.claude/skills/brigadier/\nbrigadier install codex         # writes ~/.agents/skills/brigadier/\n```\n\n`brigadier install opencode` adds the one thing a skill cannot be: a plugin that\nwatches the session and reports automatic or manual compaction. It writes\n`plugin/brigadier.js` to `~/.config/opencode/plugin/brigadier.js` and\n`README.md` to `~/.config/opencode/brigadier.README.md`.\n\n## The verified line, stated precisely\n\n`plugin/brigadier.js` reacts to the bus events named in `HANDOFF_EVENT_TYPES`,\ncurrently `session.compacted` and `session.next.compaction.started`. On\n2026-08-10, both names and their payload schemas were verified against a running\nopencode 1.18.16 darwin-arm64 by fetching `GET /doc` and enumerating its 89-event\nOpenAPI union. A probe plugin also verified that opencode loads this ESM factory,\ncalls its `event` handler with `{ event }`, and provides\n`client.tui.showToast`.\n\nNo live compaction was triggered, so emission of these events during an actual\ncompaction was not observed. Only opencode 1.18.16 was tested, and its event\nvocabulary is version-dependent. If a future build renames either event,\n`HANDOFF_EVENT_TYPES` remains the one line to change.\n\n## What the plugin does when it fires\n\nFor an automatic compaction start, it says the session is out of context. For a\nmanual compaction start, it says the compaction was requested. The completed\nevent has no reason, so its message only says the session was compacted. No\ncompaction event carries a turn count, and the plugin does not invent one.\n\nThe plugin writes one line to stderr, then attempts a toast through\n`client.tui.showToast`. Both paths are contained so the handler never throws: a\nplugin that throws takes the session's event loop with it, and a doctrine\nreminder is not worth anybody's session.\n",
    "opencode/plugin/brigadier.js":
      '/**\n * The brigadier plugin for opencode.\n *\n * opencode reads `~/.claude/skills/` natively, so the doctrine itself arrives\n * with `brigadier install claude-code` and is not duplicated here. What a skill\n * cannot do is watch the session, and that is this file\'s only job: when a\n * session compacts, say the one sentence the doctrine exists to say.\n *\n * Zero dependencies. Plain ESM, node: builtins only, no import from the\n * brigadier tree: this file is copied verbatim into\n * `~/.config/opencode/plugin/brigadier.js` and runs on its own.\n */\n\n/**\n * The event names opencode 1.18.16 declares for compaction start and completion.\n * They were read from its OpenAPI union; emission during a real compaction was\n * not observed.\n */\nexport const HANDOFF_EVENT_TYPES = [\n  "session.compacted",\n  "session.next.compaction.started",\n];\n\nconst ADVICE =\n  "Do not carry the remaining work here — write it as a brigadier plan and run `brigadier run --plan <file>`. A fresh worker gets a clean context; you keep the review.";\n\n/** True for exactly the events in `HANDOFF_EVENT_TYPES`, and for nothing else. */\nexport function isHandoffEvent(event) {\n  if (typeof event !== "object" || event === null) {\n    return false;\n  }\n  return HANDOFF_EVENT_TYPES.includes(event.type);\n}\n\n/** The sentence, qualified by the compaction reason when the event provides it. */\nexport function buildHandoffMessage(reason) {\n  if (reason === "auto") {\n    return `brigadier: this session is out of context. ${ADVICE}`;\n  }\n  if (reason === "manual") {\n    return `brigadier: this session is being compacted at your request. ${ADVICE}`;\n  }\n  return `brigadier: this session was compacted. ${ADVICE}`;\n}\n\n/**\n * Reads the reason carried by `session.next.compaction.started`. No opencode\n * compaction event carries a turn count, so the plugin does not invent one.\n */\nexport function readCompactionReason(event) {\n  if (event?.type !== "session.next.compaction.started") {\n    return null;\n  }\n  const properties = event?.properties;\n  if (typeof properties !== "object" || properties === null) {\n    return null;\n  }\n  return properties.reason === "auto" || properties.reason === "manual"\n    ? properties.reason\n    : null;\n}\n\nexport const BrigadierPlugin = async ({ client }) => {\n  return {\n    /**\n     * Never throws. A plugin that throws takes the session\'s event loop with\n     * it, and a doctrine reminder is not worth anybody\'s session.\n     */\n    event: async (input) => {\n      try {\n        const event = input?.event;\n        if (!isHandoffEvent(event)) {\n          return;\n        }\n        const message = buildHandoffMessage(readCompactionReason(event));\n        process.stderr.write(`${message}\\n`);\n        await client?.tui?.showToast?.({\n          body: { message, variant: "warning" },\n        });\n      } catch {\n        // Every failure stays inside the plugin, including malformed host input.\n        return;\n      }\n    },\n  };\n};\n\nexport default BrigadierPlugin;\n',
  });
